package org.kanger;
import java.util.*;
import java.lang.reflect.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalInitialEntry.Entry;
import org.kanger.ContextUniversalInitialEntryAudit.*;
import org.kanger.ContextWitnessResultTransport.*;
import static org.kanger.ContextUniversalContinuationMatrix.*;

/** Independent primary replay and checked controller handoff. Reflection is QA-only fault injection. */
final class ContextUniversalInitialEntryAuditMatrix {
    static int initialAudits,initialRechecks,handoffs;
    static SessionInspection inspect(Entry e,ContextUniversalFrozenBranch.Limits l,int work){return ContextUniversalInitialEntryAudit.inspectWithValidationReuse(e,l,work,4096);}
    static Receipt yes(SessionInspection s){require(s.inspection.audited&&s.inspection.output!=null&&s.metrics.entries==0&&s.metrics.verified>0,s.inspection.phase+": "+s.inspection.reason);++initialAudits;return s.inspection.output;}
    static void no(SessionInspection s,String why){require(!s.inspection.audited&&s.inspection.output==null&&s.metrics.entries==0,why+": "+s.inspection.phase+": "+s.inspection.reason);}
    static Entry entry(Snapshot x,List<Snapshot> cuts,ContextUniversalFrozenBranch.Limits l){org.kanger.ContextUniversalInitialEntry.Result r=ContextUniversalInitialEntry.assemble(x,cuts,l,4096);return ContextUniversalInitialEntryMatrix.ready(r);}
    static org.kanger.ContextUniversalGroupedRounds.Result handed(Entry e,ContextUniversalFrozenBranch.Limits l){Receipt receipt=yes(inspect(e,l,WORK));require(receipt.entry==e&&receipt.limits==l,"actual entry/policy receipt");require(ContextUniversalInitialEntryAudit.checkWithValidationReuse(receipt,WORK,4096).entries==0,"fresh initial receipt recheck closes scope");++initialRechecks;
        Frame f=ContextUniversalInitialEntryMatrix.frame(e);org.kanger.ContextUniversalGroupedRounds.SessionRun run=ContextUniversalGroupedRounds.runInitialWithValidationReuse(receipt,l,f.local,8,WORK,4096);audited(f,e.common,e.pools,e.units,e.compounds,8,run);org.kanger.ContextUniversalGroupedRounds.Result r=run.result;org.kanger.ContextUniversalGroupedRounds.SessionRun next=ContextUniversalGroupedRounds.runWithValidationReuse(e.x,e.foreign,r.output.packet,r.output.privatePools,r.symbolicOutput,r.compoundOutput,l,f.local,1,WORK,4096);audited(f,r.output.packet,r.output.privatePools,r.symbolicOutput,r.compoundOutput,1,next);same(r,next.result);require(next.result.completedRounds==1,"actual stable continuation");++continuations;++handoffs;return r;}
    static void positive()throws Exception {
        ContextUniversalSignedAlternativesMatrix.Fixture f=new ContextUniversalSignedAlternativesMatrix.Fixture(true);ContextUniversalFrozenBranch.Limits l=ContextUniversalGroupedRoundsRunner.limits(16);org.kanger.ContextUniversalGroupedRounds.Result previous=null;
        List<List<Snapshot>> orders=new ArrayList<>(ContextUniversalContinuationRefutationRunner.permutations(Arrays.asList(f.a,f.b,f.d)));
        for(List<Snapshot> members:Arrays.asList(Arrays.asList(f.b,f.d),Arrays.asList(f.d,f.b))){Snapshot g=ContextProductionNativeBinding.trusted("initial-audit",members,WORK);orders.add(Arrays.asList(f.a,g));orders.add(Arrays.asList(g,f.a));}
        for(List<Snapshot> order:orders){Entry e=entry(f.x,order,l);require(e.compounds.clauses.size()==4&&e.units.units.isEmpty(),"exact original initial carrier inventory");org.kanger.ContextUniversalGroupedRounds.Result r=handed(e,l);f.products(r);if(previous!=null)same(previous,r);previous=r;}
        ContextUniversalSeparatePrivateMatrix.Fixture two=new ContextUniversalSeparatePrivateMatrix.Fixture(false);org.kanger.ContextUniversalGroupedRounds.Result independent=handed(entry(two.x,Arrays.asList(two.a,two.c,two.b),l),l);ContextUniversalSeparatePrivateMatrix.products(two,independent);
        Snapshot group=ContextProductionNativeBinding.trusted("initial-two-private",Arrays.asList(two.c,two.a),WORK);org.kanger.ContextUniversalGroupedRounds.Result trusted=handed(entry(two.x,Arrays.asList(two.b,group),l),l);sameShared(independent,trusted);require(trusted.output.privatePools.size()==1&&independent.output.privatePools.size()==2,"trusted routing changes private cut inventory, not shared contents");
        Entry self=entry(bind(true,"!~anchor(1);"),Collections.emptyList(),l);Receipt small=yes(inspect(self,l,WORK));require(ContextUniversalInitialEntryAudit.checkWithValidationReuse(small,WORK,1).entries==0,"capacity1 original fallback preserves complete initial replay");++initialRechecks;
        System.out.println("INITIAL_ENTRY_AUDIT_POSITIVE initialAudits="+initialAudits+" initialRechecks="+initialRechecks+" checkedHandoffs="+handoffs+" independentOrders=6 trustedVariants=4 separatePrivateRoutes=2");
    }
    static void mutate(Entry e,ContextUniversalFrozenBranch.Limits l,Object object,String name,Object value,String why)throws Exception {Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);Object old=f.get(object);f.set(object,value);try{no(inspect(e,l,WORK),why);}finally{f.set(object,old);}}
    static Entry replaced(Entry e,ContextUniversalSignedUnitExchange.Exchange units,ContextUniversalCompoundExchange.Exchange compounds)throws Exception{Constructor<Entry> c=Entry.class.getDeclaredConstructor(Snapshot.class,List.class,Packet.class,Map.class,Map.class,ContextUniversalSignedUnitExchange.Exchange.class,ContextUniversalCompoundExchange.Exchange.class);c.setAccessible(true);return c.newInstance(e.x,e.foreign,e.common,e.pools,e.checks,units,compounds);}
    static void missingProof(Entry e,ContextUniversalSignedAlternativesMatrix.Fixture f,ContextUniversalFrozenBranch.Limits l)throws Exception {
        org.kanger.ContextUniversalFrozenConstraints.Result owner=e.checks.get(Cut.of(f.b));Field field=owner.getClass().getDeclaredField("proofs");field.setAccessible(true);Object old=field.get(owner);List<org.kanger.ContextUniversalFrozenConstraints.Proof> reduced=new ArrayList<>(owner.proofs);boolean removed=reduced.removeIf(p->p.clause!=null&&p.clause.literals.size()>1&&p.support.sources.equals(ContextUniversalSourceAlternativesMatrix.sources(f.x.primary.get(1).source,f.b.primary.get(0).source)));require(removed,"actual B residual alternative selected for deliberate omission");field.set(owner,Collections.unmodifiableList(reduced));
        try{ContextUniversalFrozenConstraints.check(owner,16,ContextGroundProductionRounds.budget(WORK));++checks;List<Cut> cuts=new ArrayList<>(e.checks.keySet());ContextUniversalSignedUnitExchange.Collection u=ContextUniversalSignedUnitExchange.collectWithValidationReuse(e.x,e.common,cuts,e.checks,512,256,16,WORK,4096).collection;ContextUniversalCompoundExchange.Collection c=ContextUniversalCompoundExchange.collectWithValidationReuse(e.x,e.common,cuts,e.checks,512,256,16,WORK,4096).collection;require(u.collected&&c.collected&&c.output.clauses.size()==3,"authentic remaining proofs and collector-local minima do not assert native initial completeness");Entry incomplete=replaced(e,u.output,c.output);SessionInspection rejected=inspect(incomplete,l,WORK);no(rejected,"independent original replay detects missing ordinary Source alternative");require(rejected.inspection.phase.equals("ordinary-replay"),"completeness failure located by independent ordinary replay, not carrier inconsistency");
        }finally{field.set(owner,old);}
    }
    static void refusals()throws Exception {
        ContextUniversalSignedAlternativesMatrix.Fixture f=new ContextUniversalSignedAlternativesMatrix.Fixture(true);ContextUniversalFrozenBranch.Limits l=ContextUniversalGroupedRoundsRunner.limits(16);Entry e=entry(f.x,Arrays.asList(f.a,f.b,f.d),l);Receipt receipt=yes(inspect(e,l,WORK));Entry other=entry(f.x,e.foreign,l);
        mutate(e,l,e,"common",other.common,"equal-valued different common identity");mutate(e,l,e,"units",null,"empty contents do not permit missing mandatory carrier");mutate(e,l,e,"compounds",null,"mandatory compound carrier");mutate(e,l,e,"foreign",Arrays.asList(f.a,f.b,f.b),"duplicate physical cuts");mutate(e,l,e,"checks",Collections.emptyMap(),"all supplied owning checks required");
        PrivatePool pool=e.pools.get(Cut.of(f.a));mutate(e,l,pool,"sources",Collections.emptySet(),"whole private Source inventory");mutate(e,l,pool,"declarations",Collections.emptyList(),"whole private declaration inventory");mutate(e,l,pool,"local",e.common,"missing actual original witness materialization");mutate(e,l,e,"pools",Collections.emptyMap(),"missing required witness pool");
        org.kanger.ContextUniversalFrozenConstraints.Result self=e.checks.get(Cut.of(f.x));mutate(e,l,self,"common",other.common,"actual initial owning check common");mutate(e,l,self,"exchange",e.units,"continuation input is not primary initial check");ContextUniversalNativeRows.Part part=self.input.rows.get(1).parts.get(0);mutate(e,l,part,"clauseIndex",7,"original native row part index");
        mutate(e,l,e.compounds,"clauses",Collections.emptyList(),"missing compound minima");mutate(e,l,e.compounds,"maximumAlternatives",1,"exact initial enumeration policy");missingProof(e,f,l);
        no(inspect(e,l,1),"fresh owning audit work limit returns no partial receipt");no(inspect(null,l,WORK),"REFUTED/INCOMPLETE assembly has no auditable Entry");
        org.kanger.ContextUniversalGroupedRounds.SessionRun wrong=ContextUniversalGroupedRounds.runInitialWithValidationReuse(receipt,ContextUniversalGroupedRoundsRunner.limits(16),ContextUniversalGroupedRoundsRunner.local(),8,WORK,4096);incomplete(wrong,"different actual expected policy refuses initial handoff");require(wrong.result.phase.equals("initial-entry"),"failure before controller");
        Field sources=pool.getClass().getDeclaredField("sources");sources.setAccessible(true);Object original=sources.get(pool);sources.set(pool,Collections.emptySet());try{org.kanger.ContextUniversalGroupedRounds.SessionRun stale=ContextUniversalGroupedRounds.runInitialWithValidationReuse(receipt,l,ContextUniversalGroupedRoundsRunner.local(),8,WORK,4096);incomplete(stale,"receipt is freshly checked before handoff, no ambient cached approval");require(stale.result.phase.equals("initial-entry"),"receipt refusal before any controller round");}finally{sources.set(pool,original);}
        org.kanger.ContextUniversalGroupedRounds.SessionRun tiny=ContextUniversalGroupedRounds.runInitialWithValidationReuse(receipt,l,ContextUniversalGroupedRoundsRunner.local(),8,1,4096);incomplete(tiny,"bounded initial handoff has no controller prefix");
        require(ContextUniversalInitialEntryAudit.checkWithValidationReuse(receipt,WORK,4096).entries==0,"restored independent receipt recheck after all refusals");++initialRechecks;
        System.out.println("INITIAL_ENTRY_AUDIT_REFUSALS missingOrdinaryAlternative=true collectorAuthenticationStillValid=true freshHandoffRecheck=true noPartialReceipt=true");
    }
}
